use super::is::is_combining_mark;
use super::is::is_forward_sticky_glue;
use super::is::is_kinsoku_end;
use super::is::is_numeric_run_segment;
use super::merged_segmentation::MergedSegmentation;
use super::segment::segment_contains_decimal_digit;
use super::types::SegmentBreakKind;
use super::types::SegmentationPiece;
use super::types::WhiteSpaceProfile;
use super::types::classify_segment_break_char;

pub(super) fn split_trailing_forward_sticky_cluster(text: &str) -> Option<(&str, &str)> {
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let mut split_index = chars.len();

    while split_index > 0 {
        let ch = chars[split_index - 1].1;
        if is_combining_mark(ch) || is_kinsoku_end(ch) || is_forward_sticky_glue(ch) {
            split_index -= 1;
            continue;
        }
        break;
    }

    if split_index == 0 || split_index == chars.len() {
        return None;
    }

    let byte_pos = chars[split_index].0;
    Some((&text[..byte_pos], &text[byte_pos..]))
}

pub(super) fn split_leading_space_and_marks(segment: &str) -> Option<(&str, &str)> {
    if segment.len() < 2 || !segment.starts_with(' ') {
        return None;
    }
    let rest = &segment[1..];
    if rest.chars().all(is_combining_mark) {
        Some((&segment[..1], rest))
    } else {
        None
    }
}

pub(super) fn split_segment_by_break_kind<'a>(
    segment: &'a str,
    is_word_like: bool,
    start: usize,
    ws_profile: &WhiteSpaceProfile,
) -> Vec<SegmentationPiece<'a>> {
    let mut pieces = Vec::new();
    let mut current_kind: Option<SegmentBreakKind> = None;
    let mut current_start = start;
    let mut current_word_like = false;
    let mut offset = 0;

    for ch in segment.chars() {
        let ch_len = ch.len_utf8();
        let kind = classify_segment_break_char(ch, ws_profile);
        let word_like = kind == SegmentBreakKind::Text && is_word_like;

        if let Some(ck) = current_kind {
            if kind == ck && word_like == current_word_like {
                offset += ch_len;
                continue;
            }
            pieces.push(SegmentationPiece {
                text: &segment[current_start - start..offset],
                is_word_like: current_word_like,
                kind: ck,
                start: current_start,
            });
        }

        current_kind = Some(kind);
        current_start = start + offset;
        current_word_like = word_like;
        offset += ch_len;
    }

    if let Some(ck) = current_kind {
        pieces.push(SegmentationPiece {
            text: &segment[current_start - start..offset],
            is_word_like: current_word_like,
            kind: ck,
            start: current_start,
        });
    }

    pieces
}

pub(super) fn split_hyphenated_numeric_runs(seg: MergedSegmentation) -> MergedSegmentation {
    let mut texts = Vec::new();
    let mut is_word_like = Vec::new();
    let mut kinds = Vec::new();
    let mut starts = Vec::new();

    for i in 0..seg.len() {
        let text = &seg.texts[i];
        if seg.kinds[i] == SegmentBreakKind::Text && text.contains('-') {
            let parts: Vec<&str> = text.split('-').collect();
            let should_split = parts.len() > 1
                && parts.iter().all(|part| {
                    !part.is_empty()
                        && segment_contains_decimal_digit(part)
                        && is_numeric_run_segment(part)
                });

            if should_split {
                let mut offset = 0;
                for (j, part) in parts.iter().enumerate() {
                    let split_text = if j < parts.len() - 1 {
                        format!("{part}-")
                    } else {
                        (*part).to_string()
                    };
                    texts.push(split_text.clone());
                    is_word_like.push(true);
                    kinds.push(SegmentBreakKind::Text);
                    starts.push(seg.starts[i] + offset);
                    offset += split_text.len();
                }
                continue;
            }
        }

        texts.push(text.clone());
        is_word_like.push(seg.is_word_like[i]);
        kinds.push(seg.kinds[i]);
        starts.push(seg.starts[i]);
    }

    MergedSegmentation {
        texts,
        is_word_like,
        kinds,
        starts,
    }
}
